/* eslint-disable @typescript-eslint/no-require-imports */
// One complete updater. Run this beside your existing package.json.
// Do not run the older finish/polish updater scripts afterward.
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const root = process.cwd();
const planned = new Map();
const hash = text => crypto.createHash("sha256").update(text).digest("hex");

function read(file) {
  const name = path.join(root, file);

  return fs.existsSync(name)
    ? fs.readFileSync(name, "utf8").replace(/\r\n/g, "\n")
    : null;
}

if (
  !read("package.json") ||
  !read("src/components/CampaignExperience.tsx")
) {
  throw new Error(
    "Open your existing geopolitics project folder and run this beside package.json. It is not an empty-folder installer."
  );
}

function replace(file, allowed, after, text) {
  const current = read(file);

  if (current !== null && hash(current) === after) return;

  if (
    allowed !== "*" &&
    !allowed.includes(current === null ? null : hash(current))
  ) {
    fail(file);
  }

  stage(file, after, text);
}

function edit(file, after, versions) {
  let text = read(file);

  if (text !== null && hash(text) === after) return;

  const edits = text === null ? null : versions[hash(text)];

  if (!edits) fail(file);

  for (const [start, end, value] of [...edits].reverse()) {
    text = text.slice(0, start) + value + text.slice(end);
  }

  stage(file, after, text);
}

function fail(file) {
  throw new Error(
    "Unrecognized file version: " +
      file +
      ". No source changes have been written. Keep the error; do not remove these checks."
  );
}

function stage(file, after, text) {
  if (hash(text) !== after) {
    throw new Error(
      "Integrity check failed: " +
        file +
        ". No source changes have been written."
    );
  }

  planned.set(file, text);
}

replace(".env.example",[null],"070d4fb604cc9d970a6536db451069a2b1f0a94431b6fc4bdc6676e90c625368","NEXT_PUBLIC_FIREBASE_API_KEY=\nNEXT_PUBLIC_FIREBASE_AUTH_DOMAIN=\nNEXT_PUBLIC_FIREBASE_PROJECT_ID=\nNEXT_PUBLIC_FIREBASE_STORAGE_BUCKET=\nNEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID=\nNEXT_PUBLIC_FIREBASE_APP_ID=\nFIREBASE_PROJECT_ID=\nFIREBASE_CLIENT_EMAIL=\nFIREBASE_PRIVATE_KEY=\"\"\nGROQ_API_KEY=\nGROQ_MODEL=openai/gpt-oss-20b\n");

replace("README.md","*","684ac29ddc27c6bb375cdbf3cdcd447f950e93e604e5fffad7688d9cce6ba38f","# GeoPolitics\n\nNext.js, React, TypeScript, Firebase Authentication, Cloud Firestore and Groq.\n\n## Run\n1. Install Node.js 22 or newer. Run npm ci in this folder.\n2. Preserve your existing .env.local. Fill any missing variables shown in .env.example.\n3. Enable Firebase Email/Password Authentication and Cloud Firestore.\n4. Publish src/lib/api/firestore.rules. With Firebase CLI, choose your own project using firebase use --add, then run firebase deploy --only firestore:rules,firestore:indexes.\n5. Run npx tsc --noEmit, npm run lint, then npm run dev. Open http://localhost:3000.\n6. Configure your own server-side GROQ_API_KEY. Restart and verify a NEW battle exchange produces an AI-labelled report. A fallback alone does not demonstrate live AI.\n\n## Play\nThe searchable catalogue contains 195 sovereign countries (193 UN members plus Palestine and Vatican City); each campaign uses exactly 10. 2026 populations are a checked snapshot, not a live API. Old campaigns preserve their original saved armies.\n\nClick your country with two or more soldiers, then an enemy. One attack is allowed each turn, with repeated automatic exchanges against the same target. After conquest, transfer and finish your turn. Transfer controls require two owned countries and no active attack. Place all reinforcements first. How to Play explains all PDF rules.\n\n## Six bonus areas\nGraphics/3D animation; saved history/replay; NPC difficulty; player analytics; anti-cheating through server-authoritative dice, ownership, revisions and persistent attacks; temporary alliances/diplomacy with acceptance, rejection, expiry and betrayal.\n\n## Architecture\nCampaignEngine and BattleRules own game rules. NpcStrategy makes reasoned decisions. CampaignRepository owns database transactions and deletion. API routes authenticate and validate. CampaignExperience presents saved results. BattleCommentary describes confirmed facts. Browser writes to campaign documents remain denied.\n\n## Deploy and submit\nUse a Node-compatible Next.js host, such as your Vercel project. This application needs server API routes; a static export is insufficient. Set the same environment variables on the host, including public Firebase values before building. Add the deployed domain to Firebase Authentication authorized domains. Run npm run build and deploy.\n\nProvide the PDF's source ZIP, hosted URL, application test credentials, database assessor access, and this README. Create a dedicated demo account and arrange assessor database access privately. Never include .env.local, Admin keys, node_modules, .next or backups in the submitted source ZIP.\n\n## Final live checks\nVerify owner sign-in, new campaign, population armies, round-two reinforcements, click attack, paired unsorted dice/no-loss ties, stop, conquest reward, transfers, elimination/victory, visible NPC reasons/fast-forward, refresh protection, history, real Groq output, a signed-out spectator, second-account rejection, and disposable-campaign deletion including its history.\n\nThese source changes do not certify a live deployment, provider response or assessor permissions. Complete those checks on your configured deployed application before submission. No mark or selection is guaranteed.\n\n## Finish today\nSee docs/FINISH-TODAY.md for the four-hour verification and submission plan, and docs/RUBRIC-MAP.md for evidence against all 14 marking categories.\n\n## Transfer, result and music update\nTransfers are available on your turn before or after an attack, between any owned countries, after reinforcement allocation. Leave one soldier behind; the form previews both results. After conquest, moving additional soldiers is optional. Repeated rolls against the locked target are exchanges in one attack, not new attacks; labels show the saved attack revision and exchange number. Commands at one revision are coalesced in the client and validated in a server transaction.\n\nThe result screen appears only after the final exchange has been presented and one participant owns all ten countries. It names human or NPC winners and links to the final board/history.\n\nLogin/war-room/logout use the login theme; all game phases use the battle theme. A single global director owns music; mute and volume persist. Browser audio may require an initial interaction.\n\nPerformance work: lazy graphics bundles, cached map requests across remounts, reusable WebGL resources, and commentary using the existing event subscription. These remove work; they do not establish a measured load-time improvement on your deployed network.\n\n## Apply the complete update\nSave complete-geopolitics.cjs beside package.json and run node complete-geopolitics.cjs. It contains the complete update and does not require the older updater scripts. It checks every planned source change before writing backups. If this source is already updated, use npm ci and the normal checks. Do not run an older updater afterward.\n");

replace("docs/DATA-SOURCES.md","*","795e831ba20e4206158e5c6dc10bd42ba16e253e1983beebe5c5ad4da6d738f2","# Country data\n\nThe searchable catalogue covers 193 United Nations members plus Palestine and Vatican City (195 total). This is a defined sovereign-country scope, not a list of all dependencies or disputed territories. Each campaign still contains only 10 countries.\n\n2026 population snapshot: https://www.worldometers.info/world-population/population-by-country/ (checked 5 November 2026). Populations are factual numeric values. Country names/codes and approximate latitude/longitude are adapted from mledoze/countries, distributed by the world-countries npm package: https://github.com/mledoze/countries . The derived src/data/world-countries.json dataset is provided under ODbL 1.0; see https://opendatacommons.org/licenses/odbl/1-0/. Changes: selected 195 entries, joined population values, reduced fields, ISO lowercase identifiers, alphabetical sorting. The remaining application source is not licensed by that data notice.\n\nFlags are loaded using https://flagcdn.com/w80/{iso2}.png as in the existing application. Map boundaries and visual centroids may differ from sovereign-country scope; a marker/card fallback supports countries absent from map geometry.\n");

replace("docs/FINISH-TODAY.md","*","2adaf2e1f3499d03317ee4dd2440386645ba55cc1af47524c17fdb5c3cde9c38","# Four-hour completion plan\n\nThe source has passed automated engine, type, lint, build and simulated-browser checks. Complete the live checks below using your own configuration. Record results; do not mark a check passed without observing it.\n\n| Time | Work | Evidence to keep |\n|---|---|---|\n| 0:00–0:45 | Start locally with real .env.local, enable Email/Password and Firestore, publish rules, run tests/type/lint/build | Clean terminal checks and a persisted fresh campaign |\n| 0:45–1:45 | Human turn, source click → enemy click, automatic dice, stop, transfer after conquest, round-two allocation; NPC fast-forward and decisions; alliances | Saved battle events and a rules checklist |\n| 1:45–2:30 | New Groq AI report, refresh active attack, signed-out shared viewer, second-account rejection, disposable campaign deletion including events | Live provider report, owner/security checks and database cleanup |\n| 2:30–3:15 | Deploy Node-capable Next host; set environment variables, authorize domain, repeat smoke checks on hosted URL | Working public URL and separate demo login |\n| 3:15–4:00 | Arrange required assessor database access; update README with URL/setup; prepare source ZIP and rehearsal | Submission package, URL, demo credentials and access confirmation |\n\n## Required live acceptance checklist\n- [ ] Login/signup works and existing login design is intact.\n- [ ] Search worldwide catalogue; selected country plus nine unique random countries, correct population bands and random first participant.\n- [ ] Human idle turn stays open; clicking own country then enemy begins one attack.\n- [ ] Saved dice, casualties, outcome and miniature animation agree; no second target this turn.\n- [ ] Stopping ends turn; exhaustion retains territory with one soldier.\n- [ ] Conquest reward is based on original population value; transfers retain at least one source soldier.\n- [ ] From round two, exactly two soldiers per owned country are allocated once at turn start.\n- [ ] NPC allocation, transfer, target, continue/stop decisions show reasons, including fast-forward.\n- [ ] Eliminated actors are skipped; one participant owning all ten wins.\n- [ ] Alliance acceptance/rejection, expiry, ending and attack betrayal work without changing victory requirements.\n- [ ] History, replay, analytics, difficulty, mute/volume and optional vibration work.\n- [ ] A NEW exchange shows an AI correspondent report generated by Groq, not just fallback.\n- [ ] Refresh during an attack preserves the locked target and saved progress.\n- [ ] Signed-out shared visitor can view; another signed-in account cannot mutate or delete.\n- [ ] Delete a disposable campaign from the lobby and confirm its events are removed in Firestore.\n- [ ] Repeat the core flow on the deployed URL and on mobile.\n\n## Submission\nInclude source ZIP (exclude .env.local, service-account keys, node_modules, .next and backups), hosted URL, dedicated app demo credentials, and README. Follow the PDF's database access instructions for ammarcanani@gmail.com, mc.tanner@uct.ac.za and ridewaan.hanslo@uct.ac.za. Keep keys and credentials private; grant database access through your database console as appropriate for assessment.\n\nNo source-only assessment can guarantee 56/56, bonus marks or selection. Unverified live connectivity, hosting and access remain submission blockers.\n");

replace("docs/POLISH-UPDATE.md","*","e6b11d9f95beb4162ee1daa7c782392d125c50b74da2d76551d7ff5f860deeed","# Transfer, deletion, victory, music and efficiency correction\n\nThe original PDF permits transfers during your turn, outside active attacks, retaining one source soldier. Both pre-attack and post-conquest transfers are supported, with optional post-conquest movement and visible troop previews. Stopping an attack ends the turn, so transfers must wait for your next turn after stopping.\n\nThe improved delete dialog names the campaign, explains permanent history removal, locks repeated confirmation, shows errors and allows retry. A successful repeated deletion of an already absent parent returns success; owner authorization remains enforced for existing parents. Partial cleanup failures remain marked deleting and may be retried.\n\nVictory is based on the saved engine result and all ten countries having the same owner. A human or NPC winner gets a result screen after the final animation, with a final board/history review.\n\nMultiple dice exchanges against one locked target are required by the PDF. The UI now labels attack revision and exchange number. Same-revision client requests share one promise; server revisions and the one-attack rule still validate mutations. This does not prove every live attack issue is resolved without reproducing it with real services.\n\nThe user's updated preference is login music for login/war room/logout, and battle music for the entire game. The single global director implements this while respecting mute, volume, browser visibility and audio-unlock rules.\n\nPerformance changes remove the extra commentary query, cache map requests, defer graphics and reuse WebGL buffers. No fixed speed-up percentage is claimed. All saved campaign history remains available.\n\nRequired live checks remain Firebase/Groq integration, parent/history deletion, owner vs spectator/second-account authorization and hosted performance. Source checks and simulated browser checks are not a live-service certification.\n");

replace("docs/RUBRIC-MAP.md","*","28d3ae5479f7927d69e11c45c219e0338722c9c58728ddb512960e80134f522f","# Rubric evidence map\n\nThe marksheet has 14 categories, each scored 0–4 (56 total). This is an evidence map, not an awarded score. Source verification does not prove hosted connectivity or assessor permissions.\n\n| Category | Implemented evidence | Final demonstration |\n|---|---|---|\n| Database layer | CampaignRepository separates Firestore transactions/deletion; admin configuration isolated | Show repository and deployed NoSQL database |\n| Database connection | Authenticated API writes; onSnapshot live reads | Create, refresh and reopen real saved campaign |\n| Database design | campaigns/{id}, immutable revision event documents, afterState snapshots and commentary; owner identity | Explain schema, revisions, atomic writes and history cleanup |\n| Coding structure | Next routes, reusable components, API client, services and pure engine separated | Explain folders and request-to-engine-to-repository flow |\n| OOP concepts | CampaignEngine, BattleRules, NpcStrategy, CampaignRepository, BattleCommentary, Diplomacy classes | Explain encapsulation and responsibilities with an example |\n| Validation/controls/security | Zod strict requests, integer/ownership/turn checks, revisions, server RNG, denied browser writes | Reject invalid transfer, stale action, non-owner action |\n| Functionality | 10 nations, random order, armies, locked attacks, unsorted dice, ties, transfers, reinforcements, elimination, victory | Walk through rules; run 18 automated checks |\n| Lists/search/filter/view | 195-country search, campaign search/status filters, history and public viewing | Search country and campaign; filter completed/active |\n| User interface | Responsive map/cards, dice, 3D miniatures, accessible labelled controls, status/errors and sound | Desktop and mobile human battle |\n| Navigation | Login, lobby, play, instructions, live/replay and share link | Return from manual/replay and resume campaign |\n| Authentication/authorization | Firebase login; verified owner-only API; read-only shared spectators | Owner succeeds, second account rejected, signed-out spectator reads |\n| Sophistication/complexity | Rule engine, strategic NPCs, animation clock, realtime history and temporary diplomacy | Explain one full exchange and alliance expiry |\n| AI application | Server-side Groq commentary reads confirmed exchanges; labelled fallback | Produce a NEW AI correspondent report with real configured key |\n| Overall effort | Complete source, instructions, manual, tests, six bonus areas and evidence | Demonstrate understanding and reliable hosted experience |\n\n## Six bonus demonstrations\n1. Graphics/animation: actual battle shows synchronized 3D representative infantry and dice.\n2. History/replay: inspect earlier saved board states and replay history.\n3. Difficulty: NPC risk thresholds differ; all three modes reach victory in deterministic simulations.\n4. Player analytics: human attacks, dice exchanges and attacking casualties; lobby campaign/win totals.\n5. Anti-cheating: server rolls, atomic revisions, owner checks, persisted active attack; refresh cannot reset it.\n6. Diplomacy/alliances: propose, accept/reject with a reason, expire, revoke and betray; NPC target preference.\n\nThe PDF permits an additional feature; implementing six does not establish six separate bonus mark awards. Prioritize working required functionality over adding more features.\n");

replace("docs/VERIFICATION.md","*","36dd4782c22ca97adc524bda29ada7340329472f86a4383b8de769b9a4a5d59c","# Verification — 5 November 2026\n\nPassed: fresh ZIP repair installation; safe second run; complete-today updater against the original ZIP with all target files matching; TypeScript; ESLint; production build using dummy public Firebase values; 18 specification/client checks.\n\nBrowser checks used the actual game route and UI with simulated authentication/database/API adapters: human turn waits, SVG country selection launches attack, automatic dice/conquest, two-soldier transfer, second attack blocked, spectator controls read-only, deletion through API adapter, mobile without horizontal overflow, alliance proposal/betrayal, and worldwide country search. The fixed 3D scene was visually inspected. These tests do not certify live Firebase or Groq connectivity.\n\nThe login design is preserved; its page-level music stop/start calls were removed so the global director can keep the theme playing into the war room. CampaignEngine now supports optional diplomacy while retaining the PDF battle rules. NPC late-game strategy was adjusted and all three difficulty simulations reached victory.\n\nOutstanding live checks: own Firebase credentials and published rules; new Groq report with AI source; owner vs second-account vs signed-out visitor; real parent-and-history deletion; hosted URL, authorized domain, demo credentials, assessor access and assessment submission.\n\nSix source bonus areas: graphics/animation, history/replay, difficulty, player analytics, anti-cheating, diplomacy/alliances. No exact mark or selection is guaranteed.\n\nPolish browser checks additionally passed deletion dialog cancel/retry, human and NPC victory screens, final board review, tied exchanges retaining one attack identity, stop ending the attack/turn, and game-versus-lobby music routing. These use simulated Firebase/API adapters and do not verify a live provider.\n");

