replace("src/components/CampaignCorrespondent.tsx",["72da74cba58e628aa8b44d0bcf6a06fcf4e466b2fbf7f1d9265bed2e58b2321f"],"fce3cb44fe363b9da89762d084d404ea69dd83c5cc97ca24060e634865d14ace","\"use client\";\nimport styles from \"@/styles/Campaign.module.css\";\nexport interface CorrespondentEvent {\n  revision: number; message: string; attackRevision?: number | null; exchangeNumber?: number | null;\n  dice?: { attackerLosses: number; defenderLosses: number } | null;\n  commentary?: { status: \"pending\" | \"ready\" | \"fallback\"; source?: \"groq\" | \"fallback\"; text?: string; reason?: string | null };\n}\nexport default function CampaignCorrespondent({ events, inline = false }: { events: CorrespondentEvent[]; inline?: boolean }) {\n  const event = [...events].reverse().find(item => item.dice);\n  const report = event?.commentary;\n  const label = report?.source === \"groq\" ? \"Live frequency · AI war correspondent\"\n    : report?.status === \"pending\" ? \"Live frequency · Preparing AI report\" : \"Live frequency · Battle report\";\n  return <aside className={styles.correspondentDock} style={inline ? { position: \"static\", inset: \"auto\", width: \"100%\", maxWidth: \"none\", margin: \"24px 0 0\", transform: \"none\", textAlign: \"left\" } : undefined} aria-label=\"Live war correspondent\">\n    <p className={styles.correspondentLabel}><span className={styles.correspondentDot} aria-hidden=\"true\" />{label}</p>\n    <p className={styles.correspondentText} aria-live=\"polite\">{report?.text || event?.message || \"Command is standing by. Select a target when your turn begins.\"}</p>\n    {event?.dice && <p className={styles.correspondentMeta}>Attack #{event.attackRevision ?? event.revision} · Exchange {event.exchangeNumber ?? \"saved\"} · Attacker losses {event.dice.attackerLosses} · Defender losses {event.dice.defenderLosses}</p>}\n    {report?.status === \"fallback\" && <p className={styles.correspondentMeta}>AI unavailable for this exchange · Factual fallback report</p>}\n  </aside>;\n}\n");

