replace("src/components/MusicDirector.tsx",["00abab53bb4f475ec4128402da779b849ab327650622020fa325555ef8903a34","298346f24b8d9837544d38c5f7afd6e51a6a58a8c48ba7badb7087eb27ccc6c9"],"059c91e17de5b73360f85eef1b59cfea51e3debb5f57b2ad1c381f7dae74ab81","\"use client\";\nimport { useEffect } from \"react\";\nimport { usePathname } from \"next/navigation\";\nimport { MusicPlayer } from \"@/lib/audio/MusicPlayer\";\nimport { SoundEngine } from \"@/lib/audio/SoundEngine\";\nimport { sceneForPath } from \"@/lib/audio/MusicScene\";\n\nexport default function MusicDirector() {\n  const scene = sceneForPath(usePathname());\n  useEffect(() => { MusicPlayer.setScene(scene); }, [scene]);\n  useEffect(() => {\n    const unlock = () => { MusicPlayer.resume(); void SoundEngine.unlock(); };\n    const visibility = () => { if (document.hidden) MusicPlayer.pause(); else MusicPlayer.resume(); };\n    const click = (event: MouseEvent) => {\n      if (!(event.target instanceof Element)) return;\n      const control = event.target.closest(\"button,a\");\n      if (control && !control.matches(\":disabled\")) SoundEngine.click();\n    };\n    document.addEventListener(\"pointerdown\", unlock);\n    document.addEventListener(\"keydown\", unlock);\n    document.addEventListener(\"click\", click);\n    document.addEventListener(\"visibilitychange\", visibility);\n    return () => {\n      document.removeEventListener(\"pointerdown\", unlock);\n      document.removeEventListener(\"keydown\", unlock);\n      document.removeEventListener(\"click\", click);\n      document.removeEventListener(\"visibilitychange\", visibility);\n      MusicPlayer.pause();\n    };\n  }, []);\n  return null;\n}\n");

replace("src/components/game/CampaignAnalytics.tsx",[null],"47cedd270df93093b035263c697288d7f2f06bc270186b620e83f894ae90adee","import styles from \"@/styles/Campaign.module.css\";\ntype BattleEvent = { actorId: string; action: string; dice?: { attackerLosses: number; defenderLosses: number } | null };\nexport default function CampaignAnalytics({ events }: { events: BattleEvent[] }) {\n  const yours = events.filter(event => event.actorId === \"human\");\n  const exchanges = yours.filter(event => event.dice);\n  const attacks = yours.filter(event => event.action === \"start-attack\").length;\n  const losses = exchanges.reduce((sum, event) => sum + (event.dice?.attackerLosses ?? 0), 0);\n  const inflicted = exchanges.reduce((sum, event) => sum + (event.dice?.defenderLosses ?? 0), 0);\n  return <section className={styles.panel} aria-label=\"Your attack analytics\">\n    <h2>Your battle record</h2><p className={styles.muted}>Saved human attacks in the displayed history range.</p>\n    <dl style={{ display: \"grid\", gridTemplateColumns: \"1fr auto\", gap: 10, fontSize: 12 }}>\n      <dt>Attacks launched</dt><dd>{attacks}</dd><dt>Dice exchanges</dt><dd>{exchanges.length}</dd>\n      <dt>Defender losses inflicted</dt><dd>{inflicted}</dd><dt>Your attacking losses</dt><dd>{losses}</dd>\n    </dl>\n  </section>;\n}\n");

edit("src/components/game/CampaignDeleteButton.tsx","52b26af115704a3c6b5146a5867b22d773ec06927d0af651f3c2617ce40834d3",{"df1e018be47f44ac0816d2603d7e95a78849edfe1199fc3c3ff6c12b4035254d":[[14,14,"import { useId, useRef, useState } from \"react\";\nimport { CampaignClient } from \"@/lib/api/CampaignClient\";\nimport s from \"./CampaignPolish.module.css\";\n"],[15,217,"export default function CampaignDeleteButton({ id, name, onDeleted }: {\n  id: string; name: string; onDeleted?: () => void;\n"],[222,222,"  const dialog = useRef<HTMLDialogElement>(null);\n  const pending = useRef(false);\n  const titleId = useId();\n  const descriptionId = useId();\n"],[307,378,"  async function remove() {\n"],[411,642,"    pending.current = true; setBusy(true); setError(\"\");\n"],[691,780,"      dialog.current?.close();\n      onDeleted?.();\n"],[804,940,"      setError(failure instanceof Error ? failure.message : \"Deletion failed. Please retry.\");\n"],[956,1009,"      pending.current = false; setBusy(false);\n"],[1019,1731,"  return <>\n    <button type=\"button\" className={s.deleteButton} disabled={busy} onClick={() => { setError(\"\"); dialog.current?.showModal(); }}>Delete campaign</button>\n    <dialog ref={dialog} className={s.dialog} aria-labelledby={titleId} aria-describedby={descriptionId}\n      onCancel={event => { if (pending.current) event.preventDefault(); }}>\n      <h2 id={titleId}>Delete this campaign?</h2>\n      <p id={descriptionId}><strong>{name}</strong> and its saved battles, replay history and commentary will be permanently removed. This cannot be undone.</p>\n      {error && <p className={s.error} role=\"alert\">{error} You can retry below.</p>}\n      {busy && <p role=\"status\">Removing campaign and history…</p>}\n      <div className={s.actions}>\n        <button type=\"button\" disabled={busy} onClick={() => dialog.current?.close()}>Keep campaign</button>\n        <button type=\"button\" className={s.deleteButton} disabled={busy} onClick={() => { void remove(); }}>{busy ? \"Deleting…\" : error ? \"Retry deletion\" : \"Delete permanently\"}</button>\n      </div>\n    </dialog>\n  </>;\n}\n"]]});

replace("src/components/game/CampaignPolish.module.css",[null],"df2d07e4b7677268441200bad45b01b4111662651b8b31581a7d8e1e2969efea",".victory { min-height:100vh; display:grid; place-items:center; padding:32px 18px 160px; color:#edf3fb; background:radial-gradient(ellipse at top,#34485b 0, #101a2b 45%,#050b15 85%); font-family:var(--font-geist-sans),sans-serif; }\n.victoryCard { width:min(100%,820px); text-align:center; padding:clamp(24px,5vw,64px); border:1px solid #c9ad685c; border-radius:28px; background:#0b1425e8; box-shadow:0 25px 90px #0006; }\n.emblem { display:grid; place-items:center; width:88px; height:88px; margin:0 auto 24px; border-radius:50%; border:1px solid #e3c47e; font-size:48px; color:#ebd18d; background:radial-gradient(#e0b75b33,transparent); }\n.eyebrow { color:#e1c686; font-size:11px; letter-spacing:.22em; }\n.victoryCard h1 { font-size:clamp(34px,6vw,64px); line-height:1.1; margin:18px 0; letter-spacing:-.045em; }\n.victoryCard h1:focus { outline:none; }\n.victoryCard h2 { font-size:clamp(19px,3vw,26px); font-weight:500; }\n.victoryCard p { line-height:1.7; }\n.resultStats { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; margin:32px 0; }\n.resultStats div { border:1px solid #a9bdd52d; padding:20px 8px; border-radius:12px; }\n.resultStats dt { font-size:11px; color:#b4c3d6; }\n.resultStats dd { margin:8px 0 0; font-size:26px; font-weight:700; color:#e7cf91; }\n.actions { display:flex; justify-content:center; flex-wrap:wrap; gap:12px; margin-top:24px; }\n.actions button,.actions a,.deleteButton { min-height:44px; padding:12px 16px; border-radius:9px; border:1px solid #8098b65c; background:#1b2c43; color:#f2f5fa; font:inherit; font-size:13px; cursor:pointer; text-decoration:none; }\n.actions button:disabled { opacity:.6; cursor:wait; }\n.deleteButton { border-color:#d6757566!important; background:#672c3645!important; color:#ffd7d7!important; }\n.dialog { width:min(460px,calc(100% - 32px)); box-sizing:border-box; padding:28px; border:1px solid #a9b8cf59; border-radius:20px; background:#101b2d; color:#eaf0f9; box-shadow:0 25px 100px #0009; }\n.dialog::backdrop { background:#020814bf; backdrop-filter:blur(5px); }\n.dialog p { line-height:1.7; font-size:14px; overflow-wrap:anywhere; }\n.dialog h2 { margin-top:0; font-size:24px; }\n.error { color:#ffb8b8; }\n.muted { color:#9faec3; font-size:12px; }\n.actions a:focus-visible,.actions button:focus-visible,.deleteButton:focus-visible { outline:3px solid #9ccfff; outline-offset:3px; }\n@media(max-width:480px) { .resultStats { grid-template-columns:1fr; } .resultStats div { display:flex; align-items:center; justify-content:space-between; padding:14px; } .resultStats dd { margin:0; font-size:22px; } .actions>* { width:100%; box-sizing:border-box; } }\n");

replace("src/components/game/CampaignTransfer.tsx",[null],"2127f8da3891f630781733f1fa5880dc71a57a330bfc810af21c5d1e5b17b84b","\"use client\";\nimport { useState } from \"react\";\nimport type { CampaignAction, CampaignState } from \"@/types/game-state\";\nimport s from \"./CampaignExperience.module.css\";\n\nexport default function CampaignTransfer({ state, enabled, submit }: {\n  state: CampaignState; enabled: boolean; submit: (action: CampaignAction) => void;\n}) {\n  const own = state.countries.filter(country => country.ownerId === \"human\");\n  const [from, setFrom] = useState(\"\");\n  const [to, setTo] = useState(\"\");\n  const [amount, setAmount] = useState(1);\n  const source = own.find(country => country.id === from) ?? [...own].sort((a, b) => b.soldiers - a.soldiers)[0];\n  const destination = own.find(country => country.id === to && country.id !== source?.id)\n    ?? own.find(country => country.id !== source?.id);\n  const maximum = Math.max(0, (source?.soldiers ?? 1) - 1);\n  const valid = !!source && !!destination && Number.isSafeInteger(amount) && amount >= 1 && amount <= maximum;\n  const available = enabled && own.length > 1;\n  return <section className={s.panel}>\n    <small>TROOP LOGISTICS</small><h2>Transfer troops</h2>\n    <p>During your turn, move soldiers between any two countries you own, before or after your attack. No distance restriction applies. Leave at least one soldier at the source.</p>\n    {own.length < 2 ? <p>Conquer another country to unlock transfers.</p> : <form onSubmit={event => {\n      event.preventDefault();\n      if (available && valid) submit({ type: \"transfer\", fromId: source!.id, toId: destination!.id, amount });\n    }}><fieldset disabled={!available}>\n      <label>From<select value={source?.id ?? \"\"} onChange={event => { setFrom(event.target.value); setAmount(1); }}>\n        {own.map(country => <option key={country.id} value={country.id}>{country.name} · {country.soldiers}</option>)}\n      </select></label>\n      <label>To<select value={destination?.id ?? \"\"} onChange={event => setTo(event.target.value)}>\n        {own.filter(country => country.id !== source?.id).map(country => <option key={country.id} value={country.id}>{country.name} · {country.soldiers}</option>)}\n      </select></label>\n      <label>Soldiers<input type=\"number\" min={1} max={maximum} step={1} value={amount}\n        onChange={event => setAmount(Number(event.target.value))} /></label>\n      <button type=\"button\" disabled={maximum < 1} onClick={() => setAmount(maximum)}>Use maximum ({maximum})</button>\n      {valid && <p role=\"status\">{source!.name}: {source!.soldiers} → {source!.soldiers - amount}<br />{destination!.name}: {destination!.soldiers} → {destination!.soldiers + amount}</p>}\n      {maximum === 0 && <p>This source has only one soldier. Choose another source or reinforce it first.</p>}\n      <button type=\"submit\" disabled={!valid}>Transfer soldiers</button>\n    </fieldset></form>}\n    <p className={s.hint}>{state.activeAttack ? \"Finish or stop the active attack before transferring. Stopping ends your turn.\" : state.pendingReinforcements > 0 ? \"Allocate every reinforcement before transferring.\" : !enabled ? \"Transfers are available on your live turn, outside an active attack.\" : \"After conquest, transferring additional soldiers is optional. Your one-attack limit still applies.\"}</p>\n  </section>;\n}\n");

replace("src/components/game/CampaignVictory.tsx",[null],"95ad57b4cab9d73041b7b6825ea27b24006e90346bd774fd0cf053ee9a460768","\"use client\";\nimport { useEffect, useRef, type ReactNode } from \"react\";\nimport Link from \"next/link\";\nimport type { CampaignState } from \"@/types/game-state\";\nimport s from \"./CampaignPolish.module.css\";\n\nexport default function CampaignVictory({ state, owner, onViewBoard, children }: {\n  state: CampaignState; owner: boolean; onViewBoard: () => void; children?: ReactNode;\n}) {\n  const title = useRef<HTMLHeadingElement>(null);\n  useEffect(() => { title.current?.focus(); }, []);\n  const winner = state.participants.find(participant => participant.id === state.winnerId);\n  const humanWon = state.winnerId === \"human\";\n  const army = state.countries.reduce((total, country) => total + country.soldiers, 0);\n  return <main className={s.victory}>\n    <section className={s.victoryCard} aria-labelledby=\"campaign-result-title\">\n      <div className={s.emblem} aria-hidden=\"true\">★</div>\n      <p className={s.eyebrow}>TEN NATIONS · ONE COMMAND</p>\n      <h1 id=\"campaign-result-title\" ref={title} tabIndex={-1}>{owner ? humanWon ? \"World victory\" : \"Campaign concluded\" : \"World conquered\"}</h1>\n      <h2>{winner?.name ?? \"The winning participant\"} controls all 10 countries</h2>\n      <p>{owner && humanWon ? \"Your campaign is complete. Every nation now stands under your command.\" : owner ? \"An opponent has united the world. Review the campaign and plan your next strategy.\" : \"The final conquest is saved. Explore the board and campaign history.\"}</p>\n      <dl className={s.resultStats}><div><dt>Countries</dt><dd>10 / 10</dd></div><div><dt>Final round</dt><dd>{state.round}</dd></div><div><dt>Surviving soldiers</dt><dd>{army}</dd></div></dl>\n      <nav className={s.actions} aria-label=\"Campaign result actions\">\n        <Link href=\"/lobby\">{owner ? \"Start another campaign\" : \"Visit the war room\"}</Link>\n        <button onClick={onViewBoard}>Review final board & history</button>\n      </nav>\n      <p className={s.muted}>Final result saved · One participant owns all ten nations</p>\n      {children}\n    </section>\n  </main>;\n}\n");

replace("src/components/game/DiplomacyPanel.tsx",[null],"a5ccddccbb9c427cceb454c9355f3ea81ab3295ad81d9d72d98a9c2ccb5b20d6","\"use client\";\nimport { useState } from \"react\";\nimport { Diplomacy } from \"@/lib/engine/Diplomacy\";\nimport type { CampaignAction, CampaignState } from \"@/types/game-state\";\nimport s from \"./CampaignExperience.module.css\";\n\nexport default function DiplomacyPanel({ state, enabled, submit }: {\n  state: CampaignState; enabled: boolean; submit: (action: CampaignAction) => void;\n}) {\n  const [target, setTarget] = useState(\"\");\n  const representatives = state.countries.filter((country, index, all) =>\n    country.ownerId !== \"human\" && all.findIndex(item => item.ownerId === country.ownerId) === index);\n  const selected = representatives.find(country => country.id === target);\n  const allied = !!selected && Diplomacy.allied(state, \"human\", selected.ownerId);\n  const pacts = Diplomacy.active(state).filter(pact => pact.a === \"human\" || pact.b === \"human\");\n  return <section className={s.panel}>\n    <small>EMBASSY · OPTIONAL STRATEGY</small>\n    <h2>Diplomacy & alliances</h2>\n    <p>Propose one pact per turn before attacking. NPCs accept when your total army is at least 75% of theirs. Pacts last until the start of the stated round.</p>\n    {pacts.length ? <ul>{pacts.map(pact => {\n      const partner = pact.a === \"human\" ? pact.b : pact.a;\n      return <li key={partner}>{state.participants.find(item => item.id === partner)?.name} · expires round {pact.expiresAtRound}</li>;\n    })}</ul> : <p>No active alliances.</p>}\n    <label>Diplomatic partner<select value={selected ? target : \"\"} disabled={!enabled}\n      onChange={event => setTarget(event.target.value)}>\n      <option value=\"\">Choose a surviving opponent</option>\n      {representatives.map(country => <option key={country.ownerId} value={country.id}>\n        {state.participants.find(item => item.id === country.ownerId)?.name}\n      </option>)}\n    </select></label>\n    <button disabled={!enabled || !selected || allied || !!state.diplomacyUsed || state.attackUsed}\n      onClick={() => submit({ type: \"offer-alliance\", toId: target })}>Propose alliance</button>\n    <button disabled={!enabled || !selected || !allied}\n      onClick={() => submit({ type: \"break-alliance\", toId: target })}>End selected alliance</button>\n    <p className={s.hint}>NPCs prefer feasible non-allied targets. Anyone may betray a pact by attacking; the history records it. There are no shared armies or shared victories: one participant must conquer all 10 countries.</p>\n  </section>;\n}\n");

