edit("src/components/game/RiskMap.tsx","c31ae1bd4b3eb818dbbd476d26a0170658a851d8760e7b43b78dc2871672a323",{"b864ee1e3a11338a1c86ac928229fed403470174788fb090e4e4b72e5223813b":[[665,665,"\nlet cachedWorld: Promise<World> | null = null;\nfunction loadWorld(): Promise<World> {\n  if (!cachedWorld) {\n    cachedWorld = fetch(\"/maps/world.geojson\", { cache: \"force-cache\" }).then(response => {\n      if (!response.ok) throw new Error(\"Could not load the world map.\");\n      return response.json() as Promise<World>;\n    }).catch(error => { cachedWorld = null; throw error; });\n  }\n  return cachedWorld;\n}\n"],[1598,2202,"    let active = true;\n    void loadWorld().then(data => { if (active) setWorld(data); }).catch((failure: unknown) => {\n      if (active) setError(failure instanceof Error ? failure.message : \"Could not load the world map.\");\n    });\n    return () => { active = false; };\n"]]});

