edit("src/lib/api/CampaignClient.ts","2b58f990a7ed2d04e2ccb0e16bac8c44f6e7acb7c72eec9aa6be29339b560102",{"70d30bf702386a1f640bd59f492e0b4aa57e4afb53263c1c93fb8d0a1481a4a6":[[390,390,"  private static pending = new Map<string, { fingerprint: string; promise: Promise<unknown> }>();\n\n  private static post<T>(body: unknown): Promise<T> {\n    const input = body as { operation?: string; id?: string; expectedRevision?: number };\n    if (!input || (input.operation !== \"human-action\" && input.operation !== \"npc-step\")) return this.request<T>(body);\n    const key = `${auth.currentUser?.uid}:${input.id}:${input.expectedRevision}`;\n    const fingerprint = JSON.stringify(body);\n    const existing = this.pending.get(key);\n    if (existing) {\n      if (existing.fingerprint !== fingerprint) return Promise.reject(new CampaignApiError(\"Another command is already being saved for this board. Please wait.\", 409));\n      return existing.promise as Promise<T>;\n    }\n    const promise = this.request<T>(body);\n    const entry = { fingerprint, promise };\n    this.pending.set(key, entry);\n    const clear = () => { if (this.pending.get(key) === entry) this.pending.delete(key); };\n    void promise.then(clear, clear);\n    return promise;\n  }\n\n"],[533,565,"  private static async request<T>(\n"]]});

