replace("src/lib/audio/MusicScene.ts",[null],"fc6eeb45ab6ccdddfc44c289038521e6de6ec24f2e87291bae4d400b4eec4ea4","export function sceneForPath(path: string): \"login\" | \"battle\" | \"silent\" {\n  if (/^\\/game\\/[^/]+\\/?$/.test(path)) return \"battle\";\n  if (path === \"/\" || path === \"/lobby\" || path === \"/lobby/\" || path === \"/how-to-play\") return \"login\";\n  return \"silent\";\n}\n");

