edit("src/lib/engine/CampaignEngine.ts","eafc1fa2d863d4b591a169c16363bff52da81d403ec605d249f78a93d852f42d",{"538c6e8da65599b9838573558389bccf1b2655a0b76406df91fdb3dd0704bc9b":[[0,0,"import { Diplomacy } from \"./Diplomacy\";\n"],[7512,7512,"    state.diplomacyUsed = false;\n"],[9129,9129,"      case \"offer-alliance\":\n      case \"break-alliance\": {\n        this.requireReady(state);\n        this.requireNoAttack(state);\n        const target = this.getCountry(state, action.toId);\n        if (target.ownerId === actorId) throw new Error(\"Choose another participant.\");\n        if (action.type === \"offer-alliance\") {\n          message = Diplomacy.offer(state, actorId, target.ownerId);\n        } else {\n          if (!Diplomacy.break(state, actorId, target.ownerId)) throw new Error(\"No active alliance exists with this participant.\");\n          message = `The alliance with ${state.participants.find(item => item.id === target.ownerId)?.name ?? target.name} was ended.`;\n        }\n        break;\n      }\n\n"],[13126,13126,"        const betrayed = Diplomacy.break(state, actorId, defender.ownerId);\n"],[13191,13191,"          startedAtRevision: state.revision + 1,\n"],[13383,13422,"          `against ${defender.name}.` + (betrayed ? \" This attack breaks the alliance.\" : \"\");\n"],[17355,17355,"    state.alliances = Diplomacy.active(state);\n"],[17584,17584,"        attackRevision: savedState.activeAttack\n          ? savedState.activeAttack.startedAtRevision ?? savedState.revision - savedState.activeAttack.exchangeNumber\n          : action.type === \"start-attack\" ? state.revision : null,\n        exchangeNumber: action.type === \"roll\" ? (savedState.activeAttack?.exchangeNumber ?? 0) + 1 : null,\n"]],"5520170506174775b03207217026025877a946cd8f3da725eade26210d447144":[[14057,14057,"          startedAtRevision: state.revision + 1,\n"],[18553,18553,"        attackRevision: savedState.activeAttack\n          ? savedState.activeAttack.startedAtRevision ?? savedState.revision - savedState.activeAttack.exchangeNumber\n          : action.type === \"start-attack\" ? state.revision : null,\n        exchangeNumber: action.type === \"roll\" ? (savedState.activeAttack?.exchangeNumber ?? 0) + 1 : null,\n"]]});

replace("src/lib/engine/Diplomacy.ts",[null],"a6a78758656028b5c03d983485aa2d4a559f741b7e184b3186ff110c4b119d75","import type { CampaignState } from \"../../types/game-state\";\n\n/** Temporary non-aggression pacts: no shared armies or shared victory. */\nexport class Diplomacy {\n  static active(state: CampaignState) {\n    const alive = new Set(state.countries.map(country => country.ownerId));\n    return (state.alliances ?? []).filter(pact =>\n      pact.expiresAtRound > state.round && alive.has(pact.a) && alive.has(pact.b));\n  }\n\n  static allied(state: CampaignState, a: string, b: string): boolean {\n    return this.active(state).some(pact =>\n      (pact.a === a && pact.b === b) || (pact.a === b && pact.b === a));\n  }\n\n  static break(state: CampaignState, a: string, b: string): boolean {\n    const existed = this.allied(state, a, b);\n    state.alliances = this.active(state).filter(pact =>\n      !((pact.a === a && pact.b === b) || (pact.a === b && pact.b === a)));\n    return existed;\n  }\n\n  static offer(state: CampaignState, actorId: string, targetId: string): string {\n    if (state.diplomacyUsed) throw new Error(\"Only one alliance proposal is allowed per turn.\");\n    if (state.attackUsed) throw new Error(\"Propose an alliance before starting your attack.\");\n    if (actorId === targetId) throw new Error(\"Choose another participant.\");\n    const target = state.participants.find(item => item.id === targetId);\n    if (!target || !state.countries.some(country => country.ownerId === targetId)) {\n      throw new Error(\"Choose a surviving participant.\");\n    }\n    if (target.kind !== \"npc\") throw new Error(\"This single-player campaign supports offers to NPCs.\");\n    if (this.allied(state, actorId, targetId)) throw new Error(\"An active pact already exists.\");\n    const strength = (id: string) => state.countries.filter(country => country.ownerId === id)\n      .reduce((total, country) => total + country.soldiers, 0);\n    state.diplomacyUsed = true;\n    // Stronger proposals offer credible protection; rejection still consumes the proposal.\n    if (strength(actorId) < strength(targetId) * 0.75) {\n      return `${target.name} declined the alliance: the proposed partner offers insufficient military protection.`;\n    }\n    state.alliances = [...this.active(state), { a: actorId, b: targetId, expiresAtRound: state.round + 2 }];\n    return `${target.name} accepted a temporary alliance until the start of round ${state.round + 2}: the partner offers credible military protection. Attacking either partner breaks the pact. Victory still requires all 10 countries.`;\n  }\n}\n");

edit("src/lib/engine/NpcStrategy.ts","0573cf3ba5cc85e80f3f7f91f484b894eaccf3e2d72e3af25ad3a104e992e417",{"41f0031c6e6175ac0875cfe7a1b499f9b75189b0dae41e55b9674b7dd310daf0":[[0,0,"import { Diplomacy } from \"./Diplomacy\";\n"],[3138,3180,"        Math.max(0.7, CONTINUE_RATIO[state.difficulty] - Math.max(0, state.round - 8) * 0.08);\n"],[4272,4311,"    if (state.difficulty !== \"easy\" || state.round > 8) {\n"],[5974,6010,"              country.soldiers * (state.round > 12 ? -0.5 : 2),\n"],[6146,6146,"          Number(Diplomacy.allied(state, actorId, a.country.ownerId)) -\n          Number(Diplomacy.allied(state, actorId, b.country.ownerId)) ||\n"],[6327,6364,"      Math.max(0.85, START_RATIO[state.difficulty] - Math.max(0, state.round - 8) * 0.08);\n"],[7263,7263,"        (Diplomacy.allied(state, actorId, candidate.country.ownerId)\n          ? \"; no non-allied target meets its strength threshold, so it breaks its pact\"\n          : \", preferring non-allied targets when feasible\") +\n"]],"57cc1f3c31424848839adc47ee0bcebcd58168912d7e04046021b2c8c9f63930":[[0,0,"import { Diplomacy } from \"./Diplomacy\";\n"],[6246,6246,"          Number(Diplomacy.allied(state, actorId, a.country.ownerId)) -\n          Number(Diplomacy.allied(state, actorId, b.country.ownerId)) ||\n"],[7417,7417,"        (Diplomacy.allied(state, actorId, candidate.country.ownerId)\n          ? \"; no non-allied target meets its strength threshold, so it breaks its pact\"\n          : \", preferring non-allied targets when feasible\") +\n"]]});

